import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CGSzHL4z.js";const m=JSON.parse('{"title":"Runtime API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/runtime.md","filePath":"reference/runtime.md","lastUpdated":1791952279000}'),s={name:"reference/runtime.md"};function i(d,e,n,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="runtime-api" tabindex="-1">Runtime API <a class="header-anchor" href="#runtime-api" aria-label="Permalink to &quot;Runtime API&quot;">​</a></h1><p>Every runtime note from the feature list, in one page. For signatures, parameters and examples, see the <a href="/AcesMotion-docs/api/">Runtime API</a>.</p><h3 id="install-and-layout" tabindex="-1">Install and layout <a class="header-anchor" href="#install-and-layout" aria-label="Permalink to &quot;Install and layout&quot;">​</a></h3><p>The runtime is one ModuleScript, <code>ReplicatedStorage.AcesMotion</code>, written into your place by the plugin itself.</p><h4 id="install-or-update" tabindex="-1">Install or update <a class="header-anchor" href="#install-or-update" aria-label="Permalink to &quot;Install or update&quot;">​</a></h4><ul><li>Settings &gt; About &gt; <strong>Install runtime</strong> writes the module. <strong>Update runtime</strong> sits in the same place and on the Timeline&#39;s &quot;Update runtime&quot; banner.</li><li>The module is a ModuleScript holding <code>Engine</code>, <code>Runtime</code> and <code>Packages</code> (Signal, Trove), with an <code>AcesMotion_Version</code> attribute. Its source is a short note, the MIT licence, and a <code>require</code>.</li><li>Updating keeps the root and replaces its children. Scenes are untouched, and the whole update is one undo step.</li><li>A place whose runtime is synced from files refuses the button.</li><li>About shows &quot;Not installed&quot;, &quot;0.2.0 (up to date)&quot;, &quot;(older, update it)&quot; or &quot;(newer than this plugin)&quot;.</li></ul><h4 id="require-it" tabindex="-1">Require it <a class="header-anchor" href="#require-it" aria-label="Permalink to &quot;Require it&quot;">​</a></h4><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> AcesMotion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(game.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ReplicatedStorage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AcesMotion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li><strong>Every client requires it once</strong> to receive <code>PlayForAll</code>. A LocalScript in StarterPlayerScripts is enough.</li><li>Requiring it on the server is <strong>optional</strong>. Only <code>PlayForAll</code> and a server <code>Play</code> need it there, so a client-only game never touches the server.</li></ul><h4 id="where-scenes-are-found" tabindex="-1">Where scenes are found <a class="header-anchor" href="#where-scenes-are-found" aria-label="Permalink to &quot;Where scenes are found&quot;">​</a></h4><ul><li>By name, in <code>ReplicatedStorage.AcesMotionScenes</code>, then in every folder given to <code>RegisterFolder</code>. Subfolders count too, shallowest first, never inside a scene.</li><li>A reference finds its scene by id instead: in those folders and in every folder tagged <code>AcesMotionScene</code>, wherever it is, including scenes that stream in later.</li><li>If two scenes share an id (one was copied in the Explorer), the runtime warns once and plays the first it finds.</li><li>A client can only play scenes it can see (not ServerStorage). Register the folder on every side that plays by name.</li></ul><h4 id="custom-modules" tabindex="-1">Custom modules <a class="header-anchor" href="#custom-modules" aria-label="Permalink to &quot;Custom modules&quot;">​</a></h4><p>Tagged ModuleScripts register by module name.</p><table tabindex="0"><thead><tr><th>Kind</th><th>Tag</th><th>Where</th><th>If the game can&#39;t find it</th></tr></thead><tbody><tr><td><strong>Custom generators</strong></td><td><code>AcesMotionGenerator</code></td><td>Anywhere both sides can require</td><td>Adds nothing (warned once).</td></tr><tr><td><strong>Custom constraints</strong></td><td><code>AcesMotionConstraint</code></td><td>Anywhere both sides can require</td><td>Does nothing. One that doesn&#39;t load warns once.</td></tr><tr><td><strong>Custom actions</strong></td><td><code>AcesMotionAction</code></td><td>Anywhere</td><td></td></tr></tbody></table><ul><li>Generators and constraints keep working after a rename.</li><li>An action module may return just a function (an instant action).</li><li><code>RegisterAction</code> also works for action blocks with that <code>Action</code>. They run only where the scene plays in full.</li><li><strong>Modifiers</strong> live in <code>ReplicatedStorage.AcesMotionModifiers</code> (stored; not evaluated yet).</li></ul><h4 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h4><ul><li><code>AcesMotion.Version</code> is the release version.</li><li><code>AcesMotion.FormatVersion</code> is the newest scene format it reads. A scene saved in a newer format is refused by name.</li></ul><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><p>The calls a game makes on <code>AcesMotion</code>.</p><table tabindex="0"><thead><tr><th>Function</th><th>What it does</th></tr></thead><tbody><tr><td><code>AcesMotion.Load(scene, cast?, options?)</code></td><td>Returns a <strong>Track</strong> in state Loaded: nothing bound, no camera taken, no movement lock. Errors at once if the scene is missing or newer than the runtime.</td></tr><tr><td><code>AcesMotion.Play(scene, cast?, options?)</code></td><td>Load then <code>Track:Play()</code>. On a client it plays locally.</td></tr><tr><td><code>AcesMotion.PlayForAll(scene, cast?, options?)</code></td><td>Server only. Every client (or <code>options.Audience</code>) plays the whole scene.</td></tr><tr><td><code>AcesMotion.Preload({ scene, ... })</code></td><td>Decodes scenes ahead of time.</td></tr><tr><td><code>AcesMotion.RegisterFolder(folder)</code></td><td>Adds a scene search folder.</td></tr><tr><td><code>AcesMotion.GetPlaying(actor?)</code></td><td>Lists playing tracks (or those playing <code>actor</code>).</td></tr><tr><td><code>AcesMotion.StopAll(actor?)</code></td><td></td></tr><tr><td><code>AcesMotion.OnEvent(eventName, callback)</code></td><td>Calls <code>callback(track, payload)</code> whenever an Event block or a marker named <code>eventName</code> fires in any scene on this side. Returns a function that disconnects it.</td></tr><tr><td><code>AcesMotion.Evaluate(scene, seconds, cast?)</code></td><td>Returns every actor&#39;s pose by role (track path to value). Pure, nothing written.</td></tr><tr><td><code>AcesMotion.FindById(id)</code></td><td>Returns the scene folder with that id, or nil when there&#39;s none.</td></tr><tr><td><code>AcesMotion.GetClip(model, name)</code></td><td>Returns a model&#39;s reference, or nil when there&#39;s none.</td></tr><tr><td><code>AcesMotion.GetMarkers(scene)</code></td><td>The scene&#39;s markers (Name, Time, Payload, Role), sorted by time, without playing it. Works on the server and clients, by name, folder or reference.</td></tr><tr><td><code>AcesMotion.GetEvents(scene)</code></td><td>The scene&#39;s named Event blocks (Name, Time, Duration 0, Payload, Role), sorted by time.</td></tr><tr><td><code>AcesMotion.GetMarkerTime(scene, name)</code></td><td>When the first marker or Event block called <code>name</code> fires, or nil.</td></tr><tr><td><code>AcesMotion.GetLength(scene)</code></td><td>How long the scene plays at speed 1.</td></tr></tbody></table><ul><li><code>Play</code> on the server writes roots and properties there (Roblox replicates those) and sends the joints to every client, because a joint&#39;s Transform never replicates.</li><li>Under <code>PlayForAll</code> the server keeps only the clock, so markers and Event blocks fire in server code.</li><li>The timing reads give play time at speed 1, the time <code>GetTime</code> uses: a marker&#39;s Hold counts, and a Motion Warp timed by speed counts its keyed length. The first read works a scene out and keeps it. The lists are frozen and shared, payloads too.</li></ul><h4 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h4><p>A reference is a <code>Configuration</code> tagged <code>AcesMotionClip</code>.</p><table tabindex="0"><thead><tr><th>Call</th><th>What it does</th></tr></thead><tbody><tr><td><code>AcesMotion.Play(model, &quot;Punch&quot;)</code></td><td>Plays the reference named Punch, found anywhere inside <code>model</code>.</td></tr><tr><td><code>AcesMotion.Play(reference, model)</code></td><td>The same, when you already have the reference.</td></tr><tr><td><code>AcesMotion.Play(reference, { Attacker = npc, Target = enemy })</code></td><td>Casts the roles yourself.</td></tr></tbody></table><p>Load and PlayForAll take the same arguments, and Preload and Evaluate accept a reference.</p><p>Each role goes to the first of these that has someone:</p><ol><li>The cast table in code.</li><li>The reference&#39;s cast entries.</li><li>The model, if the reference&#39;s <code>AcesMotion_Role</code> names this role.</li><li>The model, if this is the only role still empty.</li><li>The actor&#39;s game target or fallback.</li></ol><ul><li>A cast entry whose target is gone or streamed out is skipped.</li><li>If two or more roles are still empty and no role is set, the call errors and lists them.</li></ul><p>Where it plays: the <code>Anchor</code> option, else the reference&#39;s anchor, else the scene&#39;s anchor, else the scene&#39;s authored origin.</p><h4 id="registering-modules-by-hand" tabindex="-1">Registering modules by hand <a class="header-anchor" href="#registering-modules-by-hand" aria-label="Permalink to &quot;Registering modules by hand&quot;">​</a></h4><p>For modules kept somewhere untagged.</p><table tabindex="0"><thead><tr><th>Function</th><th>What it does</th></tr></thead><tbody><tr><td><code>AcesMotion.RegisterAction(name, module)</code></td><td></td></tr><tr><td><code>AcesMotion.RegisterModifier(name, module)</code></td><td></td></tr><tr><td><code>AcesMotion.RegisterGenerator(name, module)</code></td><td>A custom generator: the same table a tagged module returns. Errors at once when it has no <code>Offset</code>.</td></tr><tr><td><code>AcesMotion.RegisterConstraint(name, module)</code></td><td>A custom constraint: the same table a tagged module returns. Errors at once when it has no <code>Solve</code>.</td></tr><tr><td><code>AcesMotion.RegisterDriver(name, module)</code></td><td>A custom driver: the same table a module tagged <code>AcesMotionDriver</code> returns. Errors at once when it has no <code>Drive</code>.</td></tr></tbody></table><h4 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;Configure&quot;">​</a></h4><p><code>AcesMotion.Configure { ... }</code> sets options for the whole runtime.</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>MaxDistance</code></td><td>Off</td><td>Clients skip scenes whose anchor is farther than this number. 0 or less turns it off.</td></tr><tr><td><code>ClientReplication</code></td><td><strong>On</strong></td><td>Lets a client&#39;s Play on a model it owns replicate.</td></tr><tr><td><code>Lod</code>, <code>LodTiers</code>, <code>LodFullCount</code>, <code>CullOffscreen</code>, <code>FrameBudget</code></td><td></td><td>Level of detail, below.</td></tr></tbody></table><p><code>MaxDistance</code> never skips a scene driving the camera (Manual included) or playing in a ViewportFrame.</p><h4 id="cast" tabindex="-1">Cast <a class="header-anchor" href="#cast" aria-label="Permalink to &quot;Cast&quot;">​</a></h4><ul><li>A cast is <code>{ [Role] = Instance | { Instance } }</code>.</li><li>It&#39;s typed <code>Instance | { any }</code>, so a <code>{ Model }</code> list passes the type checker. Items that aren&#39;t instances are skipped.</li><li>An empty role plays on its <strong>fallback</strong> (usually the stand-in).</li><li>A list plays on its first item, except for an actor that repeats Per target over it (one copy per item, see Repeated actors below).</li><li>A missing role with no fallback is skipped (warned once in Studio).</li></ul><h4 id="client-plays-replicate-like-the-animator-s" tabindex="-1">Client plays replicate like the Animator&#39;s <a class="header-anchor" href="#client-plays-replicate-like-the-animator-s" aria-label="Permalink to &quot;Client plays replicate like the Animator&#39;s&quot;">​</a></h4><ul><li>A client&#39;s <code>Play</code> on its own character (or anything whose physics it owns) plays on every other client and for late joiners, control calls included.</li><li>The server checks ownership and finds the scene by its id (else its name) among the ones it can see.</li><li>It limits each player to about 10 calls a second.</li><li>It stops the play for everyone when ownership moves or the player leaves.</li><li>Plays on models the client doesn&#39;t own stay local.</li></ul><h4 id="level-of-detail" tabindex="-1">Level of detail <a class="header-anchor" href="#level-of-detail" aria-label="Permalink to &quot;Level of detail&quot;">​</a></h4><p>Level of detail is only for crowds. With up to 64 actors on screen (50 on phones; <code>Configure { LodFullCount }</code>), every visible actor poses every frame. Past that count the distance tiers start, coarser the bigger the crowd, and they switch back below 80% of the count.</p><ul><li>Settings: <code>Configure { Lod, LodTiers, LodFullCount, CullOffscreen, FrameBudget }</code> and the PlayOption <code>Important</code>.</li><li><code>LodTiers</code> sets your own distances and rates. <code>CullOffscreen = false</code> keeps offscreen actors posing.</li><li>On clients, offscreen actors don&#39;t pose and far ones pose less often:</li></ul><table tabindex="0"><thead><tr><th>Elsewhere</th><th>On phones</th></tr></thead><tbody><tr><td>Every frame within 80 studs</td><td>Every frame within 60 studs</td></tr><tr><td>30 times a second to 160 studs</td><td>30 times a second to 120 studs</td></tr><tr><td>20 times a second to 320 studs</td><td>20 times a second to 250 studs</td></tr><tr><td>12 times a second beyond</td><td>10 times a second beyond</td></tr></tbody></table><ul><li>A zoomed-in camera counts as closer.</li><li>Each actor poses on its own beat and holds the pose in between. Clocks, markers and events always run every frame.</li><li>A new play checks on its first frame whether each actor is on screen, so a move replayed over and over off screen never poses.</li><li>A frame budget (1.5 ms on phones, 4 ms elsewhere) stretches the far distances while the runtime is over it. Actors within the first tier always pose every frame.</li><li>Crowds playing the same scene share one evaluation per moment. Scenes with nothing to do skip whole frames.</li><li>Your own character, cameras and <code>Important</code> plays always pose every frame.</li><li>An <strong>attached</strong> object poses on the frames its holder poses, so the two never come apart (a far NPC&#39;s sword updates with its hand).</li><li>Between those frames it&#39;s carried along when the game moves that actor. One stuck to something posing every frame (a player, a camera) is carried too.</li><li><strong>Spawned actors</strong>, and actors whose stack only follows themselves, take Lod like the cast (a projectile far off poses less often, a rig off screen stops posing). That covers Motion Warps and any built-in constraint aimed at the actor&#39;s own role or parts, or at a spot in scene space: foot Locks, a Floor under itself.</li><li>A driver, a custom constraint, or a constraint aimed at another role keeps an actor posing every frame, even off screen.</li></ul><h4 id="rigs-in-a-viewportframe" tabindex="-1">Rigs in a ViewportFrame <a class="header-anchor" href="#rigs-in-a-viewportframe" aria-label="Permalink to &quot;Rigs in a ViewportFrame&quot;">​</a></h4><p>An inventory card, a reveal or a shop preview plays like any cast: put the rig in the frame&#39;s WorldModel before <code>Play</code>.</p><ul><li>Level of detail judges the card by how it shows, not by the world camera.</li><li>It rests while it or anything above it is hidden, its ScreenGui is disabled, it&#39;s scrolled out of a list that clips it, or it&#39;s off the screen. It picks up when shown again.</li><li>On screen it counts as a rig as far away as one that size would look. A crowd of icon-sized cards poses less often, while a big card keeps every frame.</li><li><code>MaxDistance</code> leaves it alone.</li><li>Copies the scene spawns go into the card&#39;s WorldModel.</li><li>A client&#39;s <code>Play</code> on it never replicates.</li></ul><div class="tip custom-block"><p class="custom-block-title">Fast playback</p><p>Hundreds of characters or a thousand props can play at once:</p><ul><li>Each channel is prepared once per scene, so nothing searches for keys every frame.</li><li>Joints are written without reading them back.</li><li>Events are found by time instead of scanning the scene.</li><li>The parts a frame moves go in one bulk move.</li></ul></div><h3 id="track" tabindex="-1">Track <a class="header-anchor" href="#track" aria-label="Permalink to &quot;Track&quot;">​</a></h3><p>What <code>Load</code> and <code>Play</code> return.</p><h4 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h4><p><code>Play()</code>, <code>PlayForAll()</code> (server), <code>Pause()</code>, <code>Resume()</code>, <code>SetSpeed</code>, <code>SetWeight</code>, <code>SetLayerWeight(name, weight)</code>, <code>SetLooped(bool)</code>, <code>HasCamera()</code>, <code>GetTime()</code>, <code>GetMarkerSignal(markerName)</code> and <code>Destroy()</code> do what their names say. The rest:</p><table tabindex="0"><thead><tr><th>Method</th><th>What it does</th></tr></thead><tbody><tr><td><code>Stop(fadeOut?)</code></td><td>Freezes the time and fades the pose out.</td></tr><tr><td><code>SetTime(seconds)</code></td><td>Jumps while playing and plays on. Skips instants in between.</td></tr><tr><td><code>StepTime(deltaSeconds)</code></td><td>Negative goes backwards. Fires everything crossed.</td></tr><tr><td><code>SetTimeMap(knots?)</code></td><td>Plays the time from knots <code>{ realTime, clipTime }</code> on the server clock (below). <code>nil</code> clears it.</td></tr><tr><td><code>SetCamera(bool | &quot;Manual&quot;)</code></td><td></td></tr><tr><td><code>GetCamera()</code></td><td>The scene&#39;s camera after this frame: CFrame, FieldOfView, Shot, Attached, plus the screen effects in <code>Screen</code> and the depth of field in <code>Lens</code>.</td></tr><tr><td><code>AttachCamera(blendSeconds?)</code> / <code>DetachCamera(blendSeconds?)</code></td><td>Hand the player&#39;s camera to the scene or back mid-play. Detached, the scene&#39;s camera is still worked out for GetCamera.</td></tr><tr><td><code>SetCast(cast)</code></td><td>Swaps the cast mid-play (below).</td></tr><tr><td><code>SetOptions(options)</code></td><td>Changes options mid-play (below).</td></tr><tr><td><code>IsPlaying()</code></td><td>True while paused too.</td></tr><tr><td><code>Binds(instance)</code></td><td>Whether it plays that instance as an actor.</td></tr><tr><td><code>Track.Length</code></td><td>The play&#39;s length in seconds. <code>LengthChanged</code> fires when a Motion Warp timed by speed changes it.</td></tr></tbody></table><h4 id="signals" tabindex="-1">Signals <a class="header-anchor" href="#signals" aria-label="Permalink to &quot;Signals&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Signal</th><th>Fires</th></tr></thead><tbody><tr><td><code>Started</code></td><td>On the first frame after Play, so connecting right after Play works.</td></tr><tr><td><code>Stopped</code></td><td>On Stop, or at the end of a play that does not loop.</td></tr><tr><td><code>Ended</code></td><td>When fully done: fade-out over, joints released, roots committed.</td></tr></tbody></table><ul><li>The others: <code>Looped</code>, <code>MarkerReached(markerName, payload)</code>, <code>LengthChanged(length)</code>, <code>CameraAttached</code>, <code>CameraDetached</code>, <code>ShotChanged(role?)</code>.</li><li>Signals stay connected across plays.</li></ul><h4 id="replaying-and-setters" tabindex="-1">Replaying and setters <a class="header-anchor" href="#replaying-and-setters" aria-label="Permalink to &quot;Replaying and setters&quot;">​</a></h4><ul><li>A track can be replayed: Play after it ends plays it again.</li><li>Play while it plays restarts it. An Ended handler that plays it again wins.</li><li>Setters work before and during a play and last across plays. They never change the options table you passed.</li></ul><h4 id="mid-play" tabindex="-1">Mid-play <a class="header-anchor" href="#mid-play" aria-label="Permalink to &quot;Mid-play&quot;">​</a></h4><ul><li><code>SetCast</code> lets go of the old instance (joints back to the Animator, movement lock undone) and binds the new one aligned from now.</li><li><code>SetOptions</code> re-clamps <code>Range</code>, rebinds on <code>Anchor</code>/<code>Align</code>, and applies <code>LockMovement</code>, <code>Manual</code>, <code>FadeIn</code>/<code>FadeOut</code> and <code>FreezeActors</code>/<code>CommitRoot</code> live.</li><li><code>StartTime</code> and <code>Audience</code> apply from the next Play.</li></ul><h4 id="stopping-and-time" tabindex="-1">Stopping and time <a class="header-anchor" href="#stopping-and-time" aria-label="Permalink to &quot;Stopping and time&quot;">​</a></h4><ul><li>At the end of <code>Stop(fadeOut)</code>, joints go back to what the Animator gives them. Roots and properties keep the last value written.</li><li>The weight and fades apply to joints and properties, never to the root.</li><li>Play time follows the shared server clock (<code>workspace:GetServerTimeNow()</code>), never the frame delta, so a hitch on one machine does not leave it behind.</li></ul><h4 id="time-maps" tabindex="-1">Time maps <a class="header-anchor" href="#time-maps" aria-label="Permalink to &quot;Time maps&quot;">​</a></h4><ul><li><code>SetTimeMap(knots)</code> (or the <code>TimeMap</code> option) pins play time to server time. Each knot is <code>{ realTime = serverTime, clipTime = seconds }</code>, sorted by realTime, at least one. Bad knots error.</li><li>Between knots the play runs at whatever speed reaches the next clip time. Before the first knot it holds, after the last it keeps the last stretch&#39;s speed (speed 1 with one knot).</li><li>Markers and Event blocks fire once each as the mapped time crosses them, however big the frame. A stretch that runs back plays backwards and fires what it crosses again, like a negative speed.</li><li>Set mid-play, it plays forward to where the map is now (firing what it crosses) or jumps back. <code>SetTime</code> and <code>StepTime</code> do nothing while a map is set; <code>SetSpeed</code> waits until it&#39;s cleared.</li><li>It replicates with <code>PlayForAll</code> and server <code>Play</code>, late joiners too: every machine reads the knots at its own server time and shows the same frame. A one-knot map also starts a late client&#39;s own <code>Play</code> on the right frame.</li></ul><h3 id="playoptions" tabindex="-1">PlayOptions <a class="header-anchor" href="#playoptions" aria-label="Permalink to &quot;PlayOptions&quot;">​</a></h3><p>The <code>options</code> table passed to <code>Load</code>, <code>Play</code> and <code>PlayForAll</code>.</p><h4 id="playback" tabindex="-1">Playback <a class="header-anchor" href="#playback" aria-label="Permalink to &quot;Playback&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>Speed</code></td><td><strong>1</strong></td><td></td></tr><tr><td><code>Looped</code></td><td><strong>false</strong></td><td></td></tr><tr><td><code>Weight</code></td><td><strong>1</strong></td><td>Below 1 blends over the Animator&#39;s pose.</td></tr><tr><td><code>FadeIn</code>, <code>FadeOut</code></td><td></td><td>Seconds. A fade mixes each joint with whatever pose is under it, such as the scene fading out. A joint set to Each angle on its own fades angle by angle, the way its keys move, so crossfading idle into a run never swings an arm the other way round over the head. Other joints take the shortest turn.</td></tr><tr><td><code>StartTime</code></td><td></td><td>Seconds.</td></tr><tr><td><code>TimeMap</code></td><td></td><td>Knots on the server clock (see Time maps), sent with the play in one message.</td></tr><tr><td><code>Range</code></td><td></td><td>&quot;All&quot;, &quot;LoopRegion&quot;, or <code>{ from, to }</code> in seconds.</td></tr><tr><td><code>Layers</code></td><td></td><td>Scales each named layer&#39;s authored weight.</td></tr><tr><td><code>LockMovement</code></td><td><strong>true</strong> for the local player&#39;s character</td><td></td></tr><tr><td><code>Manual</code></td><td></td><td>The runtime never advances it. Only <code>StepTime</code>/<code>SetTime</code> do.</td></tr><tr><td><code>Important</code></td><td></td><td>Always poses every frame (see Level of detail).</td></tr><tr><td><code>Templates</code></td><td></td><td><code>{ [role] = Instance }</code>: a template per spawned role, used instead of the scene&#39;s own.</td></tr></tbody></table><ul><li><code>Templates</code> lets one scene play with many looks (templates that share a skeleton). Under PlayForAll the templates must be somewhere clients see (ReplicatedStorage).</li></ul><h4 id="placement" tabindex="-1">Placement <a class="header-anchor" href="#placement" aria-label="Permalink to &quot;Placement&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>Anchor</code></td><td>The reference&#39;s anchor, else the scene&#39;s anchor, else the scene&#39;s linked origin object or fixed origin</td><td>CFrame, BasePart or Attachment: where the scene origin goes. It wins over any anchor set in the plugin, and puts the origin on the part itself.</td></tr><tr><td><code>FollowAnchor</code></td><td></td><td><code>false</code> reads the anchor once at the start instead of following it.</td></tr><tr><td><code>Align</code></td><td></td><td>Per-role override of <code>Snap</code> / <code>Blend</code> / <code>None</code>.</td></tr></tbody></table><ul><li>A part or attachment anchor is <strong>followed every frame</strong>. The scene rides it as if welded (a moving platform, a vehicle, another character), position and rotation.</li><li><strong>Anchors set in the plugin</strong> (Hub &gt; Scene origin &gt; Origin: Follows, or a reference&#39;s Origin) need no code: the runtime finds that role&#39;s part in the real cast when the play starts and follows it the same way, at the spot the plugin showed. Each side finds it in its own cast, so PlayForAll, server plays and late joiners match, and a character that streams in later is picked up then. Recasting that role mid-play moves the scene onto the new member.</li><li>If nobody plays the anchor role, Studio&#39;s Output warns once and the scene plays at its authored origin. A missing Part warns once and uses the default part.</li><li>That works under PlayForAll too: clients follow it where they see it.</li><li>A far actor that Lod holds rides along without being posed again.</li><li>An anchor inside an actor this scene moves by its root isn&#39;t followed (the actor would chase its own anchor).</li><li>A destroyed anchor leaves the scene where it last was.</li></ul><h4 id="camera" tabindex="-1">Camera <a class="header-anchor" href="#camera" aria-label="Permalink to &quot;Camera&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>Camera</code></td><td><strong>true</strong> for a local Play</td><td>A PlayForAll copy takes the camera only when the server track sets <code>Camera = true</code>. A server Play never does.</td></tr><tr><td><code>CameraBlendIn</code>, <code>CameraBlendOut</code></td><td>The scene&#39;s Camera in game settings, else <strong>0</strong> (cut)</td><td>Seconds. The view glides from the player&#39;s camera into the scene&#39;s first shot, and back when the scene lets it go.</td></tr><tr><td><code>CameraBlendInEase</code>, <code>CameraBlendOutEase</code></td><td></td><td>&quot;Smooth&quot;, &quot;Linear&quot;, &quot;EaseIn&quot;, &quot;EaseOut&quot;.</td></tr><tr><td><code>CameraStopBlend</code></td><td></td><td>Seconds back to the player&#39;s camera when stopped early. 0 snaps.</td></tr><tr><td><code>Screen</code></td><td><strong>true</strong></td><td>Draws the scene&#39;s screen effects while it drives the player&#39;s camera. <code>false</code> plays the camera without them.</td></tr></tbody></table><ul><li>The player&#39;s camera script keeps working underneath a blend, so the view lands exactly where that camera is.</li><li><code>Camera = &quot;Manual&quot;</code> works out the scene&#39;s camera every frame but leaves the player&#39;s alone, for the game to read with <code>GetCamera()</code> and apply itself.</li><li>Screen effects are bars, vignette, blur, fade, colour, bloom and each camera&#39;s depth of field. With <code>Camera = &quot;Manual&quot;</code> nothing is drawn: <code>GetCamera()</code> reports them.</li><li>Signals: <code>CameraAttached</code>, <code>CameraDetached</code>, <code>ShotChanged(role?)</code>.</li></ul><h4 id="server-and-network" tabindex="-1">Server and network <a class="header-anchor" href="#server-and-network" aria-label="Permalink to &quot;Server and network&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>Audience</code></td><td>nil = everyone</td><td>PlayForAll only: a list of players.</td></tr><tr><td><code>FreezeActors</code></td><td><strong>true</strong> for PlayForAll</td><td>The server anchors moved actors&#39; roots while playing.</td></tr><tr><td><code>CommitRoot</code></td><td><strong>true</strong> for server-owned models</td><td>The server sets final root CFrames at the end.</td></tr></tbody></table><h3 id="what-plays" tabindex="-1">What plays <a class="header-anchor" href="#what-plays" aria-label="Permalink to &quot;What plays&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What</th><th>How it plays</th></tr></thead><tbody><tr><td><strong>Joints</strong> (Motor6D, AnimationConstraint, Bone)</td><td>Blended over whatever the Animator wrote that frame, by weight. Released back on stop.</td></tr><tr><td><strong>Generators</strong></td><td>Live in games, worked out from the time like keys (so <code>SetTime</code> lands right). The same seed plays the same every time, unless a block is set to Vary each play.</td></tr><tr><td><strong>Properties</strong> of any instance</td><td>Numbers, vectors, UDim/UDim2, Color3, NumberRange, NumberSequence and ColorSequence (blended point by point), CFrame, and values that hold (Bool, Enum, Text, Asset). Also <strong>attributes</strong> and a Model&#39;s <strong>Scale</strong>.</td></tr><tr><td><strong>Joint warps</strong> (Bends Joints, Path and joints)</td><td>Solve the chain live with the same IK as Studio, so a claw closes on wherever the target really is.</td></tr></tbody></table><h4 id="root-motion" tabindex="-1">Root motion <a class="header-anchor" href="#root-motion" aria-label="Permalink to &quot;Root motion&quot;">​</a></h4><ul><li>Relative to the scene origin, each actor&#39;s root part, or per actor (Hub &gt; Scene origin &gt; Characters move from).</li><li><strong>Align</strong> applies at the start, and only to actors with a root track:</li></ul><table tabindex="0"><thead><tr><th>Align</th><th>What it does</th></tr></thead><tbody><tr><td><code>Snap</code></td><td>Teleports to the authored spot.</td></tr><tr><td><code>Blend</code></td><td>Slides over FadeIn, 0.25 s by default.</td></tr><tr><td><code>None</code></td><td>Plays where it stands.</td></tr></tbody></table><ul><li>An older scene&#39;s <code>Warp</code> plays as <code>Blend</code> (a Motion Warp bends motion onto a target).</li></ul><h4 id="audio-lanes" tabindex="-1">Audio lanes <a class="header-anchor" href="#audio-lanes" aria-label="Permalink to &quot;Audio lanes&quot;">​</a></h4><ul><li>The scene&#39;s clips play wherever the scene plays: <code>Play</code> on one client, <code>PlayForAll</code> for everyone.</li><li>Each clip plays at its volume times its lane&#39;s, flat from SoundService or from its 3D part.</li><li>Clips start partway on <code>SetTime</code>, a late start or a late join.</li><li>A clip&#39;s Sound template must be somewhere the playing side can see (ReplicatedStorage or Workspace for clients).</li><li>Roblox animations can&#39;t hold sound: Export lists &quot;Audio: N clips&quot; under what needs the runtime.</li></ul><h4 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h4><p>Attach, Detach and Back to rig keys.</p><ul><li>An attached root, joint or bone follows its target from its Attach key, keeping where it was then, with its own keys on top.</li><li>It stays put from a Detach key.</li><li>It rejoins its rig from a Back to rig key: snapped back into place, eased over its blend, or where it is.</li><li>Each Attach key carries the grip saved when it was made. An older key without one keeps the grip it has when the play reaches it.</li><li>In a game, a Detach key drops the object where it is at that moment, not at the spot saved in Studio, so it lands right when the target or the anchor is somewhere else.</li><li>A target the scene doesn&#39;t move (a dummy, an NPC, a player) is read where it stands now, so an object stuck to a walking target walks with it.</li><li>A Model actor that moves by a part (Moves by) is placed by its part of the same name in whatever model plays the role, so swapped designs line up.</li><li>Worked out from the time, so <code>SetTime</code> and <code>StepTime</code> land where a straight play would.</li><li>A target that is not in the cast holds it where it was.</li><li>A target whose root a generator moves (a Shake on its root, with or without root keys) carries what rides it the same way in a game as in Studio.</li></ul><h4 id="held-props-ride-a-joint" tabindex="-1">Held props ride a joint <a class="header-anchor" href="#held-props-ride-a-joint" aria-label="Permalink to &quot;Held props ride a joint&quot;">​</a></h4><ul><li>While an Attach key holds a part or model actor on a part (a hand) or an Attachment in one, the runtime joins it to the holder with a Motor6D named <code>AcesMotionHold</code> inside the prop.</li><li>That happens when the prop is unanchored or its <strong>Unanchor</strong> switch is on.</li><li>A held prop costs nothing per frame. Keys on the prop itself still apply on top.</li><li>A model&#39;s parts that aren&#39;t joined to its main part (its Moves by part, else its PrimaryPart) are welded to it for the hold (<code>AcesMotionHoldWeld</code>).</li><li>The joint goes when the hold ends: a Detach key, another target, <code>SetTime</code> outside the hold, <code>Stop</code>. Anchored, Massless and CanCollide go back to how they were, so the prop stays where it was.</li><li>Each client makes its own joint (nothing replicates); the server never does.</li><li>These keep the per-frame math: an anchored prop with Unanchor off, a held rig, a rig&#39;s own joint, a Bone target, and a prop with constraints or drivers.</li></ul><h4 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h4><p>Track To, Copy, Limit, Floor and the rest.</p><ul><li>They run live after keys and attachments, each row&#39;s stack in order with its generators, so a constrained camera aims at whoever plays the target role.</li><li>A constraint whose target isn&#39;t in the cast does nothing.</li><li>A distance fade weighs each constraint by how far it is from what it measures to, every frame.</li></ul><h4 id="drivers" tabindex="-1">Drivers <a class="header-anchor" href="#drivers" aria-label="Permalink to &quot;Drivers&quot;">​</a></h4><p>Copy, Distance, Axis, Speed, Property and custom.</p><ul><li>They run live in the same stacks as generators and constraints, on roots, joints, properties or one channel of them.</li><li>A source the scene animates is read from the scene at that moment, so <code>SetTime</code> and late joins land right.</li><li>A source the scene doesn&#39;t animate (a game-set attribute, a player, a physics object) is read live every frame. Its Speed and Smooth follow it between frames.</li><li>A driver whose source is missing does nothing (the keys play). One that reads what it drives is ignored.</li><li>A whole Color3 driven by a number picks its colour from the block&#39;s colour ramp.</li></ul><h4 id="roles-the-game-fills-in" tabindex="-1">Roles the game fills in <a class="header-anchor" href="#roles-the-game-fills-in" aria-label="Permalink to &quot;Roles the game fills in&quot;">​</a></h4><p>An actor&#39;s Filled by.</p><ul><li>When the game&#39;s cast leaves the role out, the runtime fills it with one of these: <ul><li>the local player&#39;s character</li><li>the nearest player&#39;s character (nearest to the scene origin)</li><li>the player&#39;s camera</li><li>the nearest (or first) object with a tag</li></ul></li><li>It picks again 10 times a second as players respawn and move.</li><li>A role the game casts itself always wins.</li><li>The server has no local player or camera, so those roles stay empty there.</li></ul><h4 id="calls" tabindex="-1">Calls <a class="header-anchor" href="#calls" aria-label="Permalink to &quot;Calls&quot;">​</a></h4><p>Calls run in Full mode, not in the server&#39;s timing copy.</p><table tabindex="0"><thead><tr><th>Call</th><th>Details</th></tr></thead><tbody><tr><td>A sound&#39;s <code>Play()</code> / <code>Stop()</code></td><td>Clones of the Sound with its effects and SoundGroup, or an AudioPlayer with its wires, playing the key&#39;s region, loop, speed and fades. At most 16 copies per sound, the oldest stopped first.</td></tr><tr><td>An emitter&#39;s <code>Emit()</code> and <code>Clear()</code></td><td><code>Emit()</code> uses the burst&#39;s own particle life.</td></tr><tr><td>A Trail&#39;s <code>Clear()</code></td><td></td></tr><tr><td>A VideoFrame&#39;s <code>Play()</code> / <code>Pause()</code></td><td></td></tr></tbody></table><h4 id="camera-actors" tabindex="-1">Camera actors <a class="header-anchor" href="#camera-actors" aria-label="Permalink to &quot;Camera actors&quot;">​</a></h4><ul><li>They take the camera (CFrame and FOV) on a client&#39;s full play unless <code>Camera</code> is false. <code>SetCamera(false)</code> gives it back mid-play.</li><li>A switch key&#39;s <strong>Blend</strong> glides into its shot from the camera before it, eased in and out, the outgoing camera still moving as keyed.</li><li>The first shot, or one after a gap, glides from the player&#39;s view.</li><li>With <strong>several camera actors</strong>, only the live one drives the camera. The scene&#39;s Camera track switch keys choose it: <ul><li>the last switch at or before the time</li><li>before the first switch, its camera</li><li>with no switches, the first camera actor in the cast</li><li>a muted camera or track is skipped</li></ul></li><li>Scrubbing, <code>SetTime</code> and playing all agree.</li></ul><h4 id="spawned-actors" tabindex="-1">Spawned actors <a class="header-anchor" href="#spawned-actors" aria-label="Permalink to &quot;Spawned actors&quot;">​</a></h4><ul><li>Cloned from their template into <code>workspace.AcesMotionSpawned</code> at their spawn frame, anchored, at their socket or the origin.</li><li>The template is found by its <code>AcesMotionTemplate</code> tag and id wherever it is, else by its saved path like <code>ReplicatedStorage/AcesMotionTemplates/SlashArc</code>.</li><li>Destroyed at their Until, or Lifetime seconds after the scene ends, or when it ends.</li><li>With <strong>Linger</strong> on, a spawned actor that disappears mid-scene stays its Lifetime more so its trails and particles finish.</li><li>A <strong>Parent to</strong> actor goes inside that part, welded.</li><li>Scrubbing back before the spawn frame removes the clone.</li><li>A looped play keeps its clones between passes (out of the world, put back on the next pass) instead of cloning again.</li><li>Under PlayForAll the clones are client-side (visual only).</li></ul><h4 id="markers-and-action-blocks" tabindex="-1">Markers and action blocks <a class="header-anchor" href="#markers-and-action-blocks" aria-label="Permalink to &quot;Markers and action blocks&quot;">​</a></h4><ul><li><strong>Markers</strong> fire <code>MarkerReached</code> and <code>GetMarkerSignal</code>.</li><li><strong>Event blocks</strong> (params <code>Name</code>, <code>Payload</code>) fire those and <code>OnEvent</code>.</li><li>Other action blocks run the module registered under their <code>Action</code> name, only in Full mode.</li><li>Blocks are added on the Timeline&#39;s action tracks; their parameters are edited in the Inspector from the next update.</li></ul><h4 id="motion-warps" tabindex="-1">Motion Warps <a class="header-anchor" href="#motion-warps" aria-label="Permalink to &quot;Motion Warps&quot;">​</a></h4><ul><li>They re-fit each trip to where things really are. A target the scene doesn&#39;t move is read where it stands now.</li><li>Aim at launch keeps where it was when the trip began, each play and each loop.</li><li>After the trip a warp keeps its landing until the next warp on the row, or until an Attach or Detach key on that row takes the actor over (a sticky shot that drops later).</li><li>One timed By speed is worked out when the play reaches it (from where its start and target are then). The play&#39;s <code>Length</code> follows, and <code>LengthChanged</code> fires.</li><li>Marker <strong>holds</strong> freeze the scene (or one actor). A Camera kick shakes the local camera over a scene marker&#39;s hold.</li></ul><h4 id="repeated-actors" tabindex="-1">Repeated actors <a class="header-anchor" href="#repeated-actors" aria-label="Permalink to &quot;Repeated actors&quot;">​</a></h4><ul><li>A Per target actor plays one copy per item of its Over role&#39;s list (<code>Cast = { Targets = { a, b, c } }</code>). An empty list plays none.</li><li>The other items play as &quot;Targets#2&quot;, &quot;Targets#3&quot;... in the cast, which networked copies use, and each copy lands on its own item.</li><li>A Count actor plays its copies with their Spread.</li><li>Each copy has its own warp, timing and Stagger, and its actor markers carry <code>Target</code>.</li><li>The play lasts until the last copy ends.</li></ul><h4 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h4><ul><li>Layers play in games as in Studio: each actor&#39;s keys on a layer blend over Base by the layer&#39;s mode, weight curve, mask, mute and solo.</li><li><code>options.Layers = { Polish = 0.5 }</code> and <code>Track:SetLayerWeight(name, weight)</code> scale a layer&#39;s authored weight by its name from the next frame (under PlayForAll too).</li><li>Not at runtime yet: modifiers.</li></ul><h3 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h3><p>One RemoteEvent, <code>AcesMotionRemote</code>, under the runtime module, from server to clients.</p><ul><li>The only thing a client sends is its own play on a model it owns, which the server checks and relays.</li><li>Messages carry the server clock, so a client re-anchors rather than drifts. It jumps without firing events when more than 0.05 s off.</li><li>Each play sends its scene as the folder, the scene&#39;s permanent id and its name. The receiving side uses the first it can resolve, so renamed scenes, scenes found through a reference and late joiners all get the same scene.</li><li><strong>Late joiners</strong> receive the live tracks and start at the current time (a looped one wrapped).</li><li><strong>Streamed-in actors</strong> (StreamingEnabled): cast members are tagged <code>AcesMotionCast</code> with an <code>AcesMotion_CastId</code> attribute, and a client binds a member that was not streamed in when it appears.</li><li>The server sends the anchor it resolved and each moved actor&#39;s start root, so every client aligns alike.</li><li>A server <code>Play</code> shares itself as a joints-only copy (plus the owning client&#39;s own character root).</li></ul><h4 id="frozen-actors-under-playforall" tabindex="-1">Frozen actors under PlayForAll <a class="header-anchor" href="#frozen-actors-under-playforall" aria-label="Permalink to &quot;Frozen actors under PlayForAll&quot;">​</a></h4><ul><li><code>FreezeActors</code> anchors moved actors on the server while a PlayForAll plays.</li><li><code>CommitRoot</code> then pivots them to where the clients left them, and unanchors them. Attach keys, Motion Warps, root generators and constraints are included: the server solves those roots each frame meanwhile, so launches and drop spots match.</li><li>An actor counts as moved when the scene keys, attaches or stacks its root. Player characters are never frozen.</li><li><code>Track.Started</code> / <code>Ended</code> let games pause and resume NPC logic.</li></ul><div class="tip custom-block"><p class="custom-block-title">Client-only games</p><p>The server never needs to require the runtime for a client-only game.</p></div>',121)])])}const u=t(s,[["render",i]]);export{m as __pageData,u as default};
